          // may retry instead of replaying this settled rejection.
          if (pending.get(key) === promise) pending.delete(key);
          throw reason;
        }
      );
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

