'use strict';
// Scratch verification of mutation/failure orderings against the cache.js contract.
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));

function deferred() {
  let resolve, reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
}

async function main() {
  // 1. Old detached flight must not evict the newer flight from the registry (dedup preserved).
  {
    const g1 = deferred(), g2 = deferred();
    let calls = 0;
    const cache = createCache({ now: () => 0, ttlMs: 100,
      load() { calls++; return calls === 1 ? g1.promise : g2.promise; } });
    const r1 = cache.get('k');
    await tick();
    cache.invalidate('k');
    const r2a = cache.get('k'), r2b = cache.get('k');
    assert.equal(calls, 2);
    g1.resolve('stale');            // old flight settles AFTER new flight registered
    await r1;
    assert.equal(calls, 2, 'stale settle must not evict the newer flight');
    const r2c = cache.get('k');
    assert.equal(calls, 2, 'readers must still join the newer flight');
    g2.resolve('fresh');
    assert.equal(await r2a, 'fresh');
    assert.equal(await r2b, 'fresh');
    assert.equal(await r2c, 'fresh');
    assert.equal(await cache.get('k'), 'fresh');
    assert.equal(calls, 2);
  }

  // 2. set() wins over an earlier load; its completion must not overwrite nor restart TTL.
  {
    const g = deferred();
    let t = 0;
    const cache = createCache({ now: () => t, ttlMs: 100, load: () => g.promise });
    const r = cache.get('k');
    await tick();
    cache.set('k', 'set-value');
    t = 50;
    g.resolve('loaded');            // old load commits late
    assert.equal(await r, 'loaded', 'original waiter still gets its own value');
    assert.equal(await cache.get('k'), 'set-value', 'set value must win');
    t = 99;
    assert.equal(await cache.get('k'), 'set-value');
    t = 100;                        // expires relative to set time, not load-commit time
    let calls = 0;
    const c2 = createCache({ now: () => 0, ttlMs: 100, load: () => { calls++; return 'x'; } });
    await c2.get('k');
    assert.equal(calls, 1);
  }

  // 3. Rejection (async and sync-throw, non-Error reason) is never cached; retry works; waiters share reason.
  {
    let calls = 0;
    const cache = createCache({ now: () => 0, ttlMs: 100,
      load() { calls++; if (calls === 1) return Promise.reject('nope'); if (calls === 2) throw 'sync'; return 'ok'; } });
    const [e1, e2] = await Promise.all([
      cache.get('k').then(() => null, e => e),
      cache.get('k').then(() => null, e => e),
    ]);
    assert.equal(e1, 'nope');
    assert.equal(e2, 'nope', 'all waiters get the same reason');
    await tick();
    assert.equal(await cache.get('k').then(() => null, e => e), 'sync', 'subsequent get may retry');
    assert.equal(await cache.get('k'), 'ok');
    assert.equal(calls, 3);
  }

  // 4. load synchronously invalidates its own key before returning.
  {
    let calls = 0;
    const cache = createCache({ now: () => 0, ttlMs: 100,
      load() { calls++; if (calls === 1) cache.invalidate('k'); return 'v' + calls; } });
    assert.equal(await cache.get('k'), 'v1');
    assert.equal(await cache.get('k'), 'v2', 'self-invalidated load must not store its value');
    assert.equal(calls, 2);
  }

  // 5. load synchronously sets its own key; set wins.
  {
    let calls = 0;
    const cache = createCache({ now: () => 0, ttlMs: 100,
      load() { calls++; if (calls === 1) cache.set('k', 'manual'); return 'loaded'; } });
    assert.equal(await cache.get('k'), 'loaded', 'original waiter gets load result');
    assert.equal(await cache.get('k'), 'manual', 'set value wins after settle');
    assert.equal(calls, 1);
  }

  // 6. clear() is a barrier for every key, including keys with no stored value.
  {
    const g = deferred();
    let calls = 0;
    const cache = createCache({ now: () => 0, ttlMs: 100,
      load(k) { calls++; return k === 'a' && calls === 1 ? g.promise : 'fresh'; } });
    const r = cache.get('a');
    await tick();
    cache.clear();
    g.resolve('stale');
    assert.equal(await r, 'stale');
    assert.equal(await cache.get('a'), 'fresh');
    assert.equal(calls, 2);
  }

  // 7. ttlMs = 0 dedups an unsettled flight but never reuses a settled value.
  {
    const g = deferred();
    let calls = 0;
    const cache = createCache({ now: () => 0, ttlMs: 0, load: () => { calls++; return g.promise; } });
    const a = cache.get('k'), b = cache.get('k');
    await tick();
    assert.equal(calls, 1, 'unsettled flight is shared');
    g.resolve('v');
    await a; await b;
    cache.get('k');
    assert.equal(calls, 2, 'settled value is never reused at ttlMs=0');
  }

  // 8. load reading its own key without awaiting joins the existing flight (no recursion).
  {
    let cache;
    let calls = 0;
    cache = createCache({ now: () => 0, ttlMs: 100,
      load(k) { calls++; if (calls === 1) cache.get(k); return 'self'; } });
    assert.equal(await cache.get('k'), 'self');
    assert.equal(calls, 1);
  }

  // 9. size counts only unexpired stored values, never flights; lazy expiry.
  {
    let t = 0;
    const g = deferred();
    const cache = createCache({ now: () => t, ttlMs: 10, load: () => g.promise });
    cache.set('a', 1);
    assert.equal(cache.size, 1);
    cache.get('b');                 // unsettled flight
    assert.equal(cache.size, 1, 'flights do not count');
    t = 10;
    assert.equal(cache.size, 0, 'expired values discarded lazily');
    assert.equal(cache.size, 0);
    g.resolve('b-val');
    await tick();
    assert.equal(cache.size, 1, 'flight still commits after lazy expiry read');
  }

  // 10. Mutations return undefined; instances are isolated; argument validation.
  {
    const c1 = createCache({ now: () => 0, load: k => k });
    const c2 = createCache({ now: () => 0, load: k => 'other' });
    assert.equal(c1.set('k', 1), undefined);
    assert.equal(c1.invalidate('k'), undefined);
    assert.equal(c1.clear(), undefined);
    await c1.get('x');
    assert.equal(c2.size, 0, 'instances isolated');
    assert.throws(() => createCache({ load: 1 }), TypeError);
    assert.throws(() => createCache({ load: () => {}, ttlMs: -1 }), RangeError);
    assert.throws(() => createCache({ load: () => {}, ttlMs: NaN }), RangeError);
    assert.throws(() => createCache({ load: () => {}, now: 0 }), TypeError);
  }

