  {
    let calls = 0;
    const cache = createCache({ now: () => 0, ttlMs: 100, load: () => { calls++; return undefined; } });
    assert.equal(await cache.get('k'), undefined);
    assert.equal(await cache.get('k'), undefined);
    assert.equal(calls, 1, 'undefined value is cached');
  }

