details.newText:
'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key);
      // Only the flight still registered for the key may remove itself and
      // commit. A flight detached by forget/clear (invalidate/set/clear)
      // still settles its own waiters, but must not store its stale value
      // nor evict a newer flight registered after the detachment.
      let promise;
      promise = Promise.resolve().then(work).then(
        value => {
          if (pending.get(key) === promise) {
            pending.delete(key);
            commit(value);
          }
          return value;
        },
        reason => {
          // Rejections are never cached; drop the flight so a later get
          // may retry instead of replaying this settled rejection.
          if (pending.get(key) === promise) pending.delete(key);
          throw reason;
        }
      );
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

